  function SelectSettingElement({ FnId, SettingKey, onChange }) {
    return (
      <div className="fn-option fn-option-select">
        <span className="config-name">{FnId}:</span>
        <select
          className="custom-config-select custom-config-select-medium"
          value={SettingKey}
          onChange={onChange}
        >
          <option value="FN_1">{(chrome.i18n.getMessage("okiopointOption1"))}</option>
          <option value="FN_2">{(chrome.i18n.getMessage("okiopointOption2"))}</option>
          <option value="FN_3">{(chrome.i18n.getMessage("okiopointOption3"))}</option>
          <option value="FN_4">{(chrome.i18n.getMessage("okiopointOption4"))}</option>
          <option value="FN_5">{(chrome.i18n.getMessage("okiopointOption5"))}</option>
        </select>
      </div>
    );
  }

  function SelectOptionElement({ Value, List, Title, Pos, onChange }) {
    return (
      <div className={`fn-option fn-option-select half ${Pos}`}>
        <span className="config-name">{Title}</span>
        <select className="custom-config-select custom-config-select-small" value={Value} onChange={onChange}>
          {(() => {
            if (List.length == 3) {
              return (
                <React.Fragment>
                  <option value={List[0]}>{(chrome.i18n.getMessage("optionSize3"))}</option>
                  <option value={List[1]}>{(chrome.i18n.getMessage("optionSize2"))}</option>
                  <option value={List[2]}>{(chrome.i18n.getMessage("optionSize1"))}</option>
                </React.Fragment>
              );
            }
            if (List.length == 4) {
              return (
                <React.Fragment>
                  <option value={List[0]}>{(chrome.i18n.getMessage("optionSize4"))}</option>
                  <option value={List[1]}>{(chrome.i18n.getMessage("optionSize3"))}</option>
                  <option value={List[2]}>{(chrome.i18n.getMessage("optionSize2"))}</option>
                  <option value={List[3]}>{(chrome.i18n.getMessage("optionSize1"))}</option>
                </React.Fragment>
              );
            }
          })()}
        </select>
      </div>
    );
  }

  // OKIOPointSwitch 元件
  function OKIOPointSwitch({ PointSwitch, PointDisable, onChange }) {
    // 如果不支援則阻擋點擊事件，並設定成 off
    const style = {
      pointerEvents: PointDisable ? "none" : "auto",
    };
    return (
      <React.Fragment>
        <div className="config-item okiopoint-item-switch">
          <span>{(chrome.i18n.getMessage("enableTxt"))}</span>
          <div className={`okiopoint-switch ${PointSwitch ? "on" : "off"}`} onClick={onChange} style={style}>
            <img src="./image/config_panel/switch-on.png"></img>
            <img src="./image/config_panel/switch-off.png"></img>
          </div>
          <span>{(chrome.i18n.getMessage("disableTxt"))}</span>
        </div>
      </React.Fragment>
    );
  }

  function OKIOPointSpeed({ Max, Min, Step, MoveSpeed, DefaultSpeed, setMoveSpeed }) {
    return (
      <React.Fragment>
        <div className="config-item okiopoint-item-speed">
          <div style={{ display: "flex", justifyContent: "space-between" }}>
            <span className="config-name">{(chrome.i18n.getMessage("panSpeedTxt"))}</span>
            <SliderOptionElement
              Max={Max}
              Min={Min}
              Step={Step}
              Value={Max - MoveSpeed + Min}
              DisplayValue={(Max - MoveSpeed + Min) / Step - 1}
              onInput={(Value) => {
                if (Value <= Max && Value >= Min) {
                  setMoveSpeed(Max - Value + Min); // input element value to speed value
                }
              }}
            />
          </div>
          <div className="config-reset">
            <img
              className="tooltip"
              title={(chrome.i18n.getMessage('resetDefault'))}
              src="./image/config_panel/OKIOPoint-config_reset.png"
              onClick={() => {
                setMoveSpeed(DefaultSpeed);
              }}
            ></img>
          </div>
        </div>
      </React.Fragment>
    );
  }

  function resetAvatar() {
    let img = document.getElementById("avatarImage");
    img.src = "./image/Shutterstock_445756432.png";
    localStorage.setItem("AvatarImage", "./image/Shutterstock_445756432.png");
    $(".holder").removeClass("active");
    $("#builtIn").children().eq(0).addClass('active');
    $('#delete-avatar').attr('disabled', 'disabled');
    redrawAvatar();
  }

